CREATE OR REPLACE FUNCTION public.coach_rx_catalog_revision() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('catalog',(SELECT md5(coalesce(string_agg(md5(to_jsonb(c)::text),'' ORDER BY c.slug),'')) FROM public.wk_movement_catalog c),'reviews',(SELECT md5(coalesce(string_agg(md5(to_jsonb(a)::text),'' ORDER BY to_jsonb(a)::text),'')) FROM public.exercise_vault_audit a WHERE a.action IN ('equipment_corrected','review_approved','make_live'))); $$;
REVOKE ALL ON FUNCTION public.coach_rx_catalog_revision() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.coach_rx_catalog_revision() TO service_role;
CREATE OR REPLACE FUNCTION public.coach_rx_commit_certified(p_user uuid,p_rx uuid,p_date date,p_choice text,p_rows jsonb,p_slots text[],p_safety jsonb,p_expected_updated_at timestamptz) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; current_revision jsonb; BEGIN PERFORM public.wk_lock_plan_day(p_user,p_date); IF p_choice IN ('use_instead','add_alongside') THEN current_revision:=public.coach_rx_safety_revision(p_user,p_date); IF p_safety->'expected_revision' IS NULL OR p_safety->'expected_revision' IS DISTINCT FROM current_revision THEN RAISE EXCEPTION 'Safety inputs changed; refresh and check again' USING ERRCODE='40001'; END IF; IF p_safety->'expected_catalog_revision' IS NULL OR p_safety->'expected_catalog_revision' IS DISTINCT FROM public.coach_rx_catalog_revision() THEN RAISE EXCEPTION 'Catalog or owner review changed; refresh and check again' USING ERRCODE='40001'; END IF; IF current_revision->'ledger' IS NULL OR current_revision->'ledger'='null'::jsonb OR jsonb_array_length(current_revision->'snapshots')=0 THEN RAISE EXCEPTION 'Saved plan and workload required'; END IF; END IF; result:=public.coach_rx_commit_choice(p_user,p_rx,p_date,p_choice,p_rows,p_slots,p_safety,p_expected_updated_at); RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.coach_rx_commit_certified(uuid,uuid,date,text,jsonb,text[],jsonb,timestamptz) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.coach_rx_commit_certified(uuid,uuid,date,text,jsonb,text[],jsonb,timestamptz) TO service_role;
COMMENT ON FUNCTION public.coach_rx_catalog_revision() IS 'Service-only catalog and owner-review fingerprints; no athlete data returned. Used by coach day-lock commit to reject stale certification.';